$_MODULE['<{vatnumber}prestashop>vatnumber_6f9b2f201c3628a96dfce2b15883109c'] = 'Les clients ayant une adresse dans ce pays paient toujours la TVA, meme avec un numero de TVA valide. Choisissez le pays ou votre entreprise est immatriculee.';
$_MODULE['<{vatnumber}prestashop>vatnumber_f324dff86d093d0f37bef63ebd8267d9'] = 'Demande a VIES, la base de donnees de l\'UE, si un numero de TVA existe vraiment. Laissez cette option activee ; desactivez-la uniquement pendant les tests.';
$_MODULE['<{vatnumber}prestashop>vatnumber_a614a4e4d6e1f4ea4377757c5e21b611'] = 'Active : le client paie la TVA jusqu\'a ce que VIES ait confirme le numero. Desactivez-la pour accorder l\'exoneration tout de suite et verifier le numero ensuite.';
$_MODULE['<{vatnumber}prestashop>vatnumber_1f4d5e9883cb3048cadf3b36d73a5941'] = 'Le numero de TVA de votre boutique avec le code pays. Renseignez-le pour recevoir de VIES un ID de consultation comme preuve de chaque verification.';
$_MODULE['<{vatnumber}prestashop>vatnumber_bb4e66281d149d3ad6b73f2fd31ffa44'] = 'Les numeros des clients sans commande ni changement d\'adresse depuis cette date ne sont pas verifies. Utilisez-le apres une mise a jour pour ignorer des annees d\'anciennes adresses.';
$_MODULE['<{vatnumber}prestashop>vatnumber_8a70393e5b4792494e0231b3b3309130'] = 'Saisissez un numero de TVA avec le code pays pour le verifier immediatement aupres de VIES. Le resultat vaut aussitot pour chaque client qui utilise ce numero.';
