$_MODULE['<{vatnumber}prestashop>intro_4cd91094c199d113383602668f77405e'] = 'Numeros de TVA rejetes';
$_MODULE['<{vatnumber}prestashop>intro_e29d8c976dabe0f74f1516a02ffddb4d'] = 'Ces numeros ont ete rejetes par VIES ou ne peuvent pas exister en raison de leur format. Un tel numero n\'obtient jamais l\'exoneration de TVA. Le client et la derniere commande correspondent a l\'adresse sur laquelle le numero a ete vu en dernier.';
$_MODULE['<{vatnumber}prestashop>intro_c45d25c3d382ec4f3be5371fa47694ee'] = 'Que faire : demandez au client le bon numero. Si une commande a ete passee sans TVA sous ce numero, verifiez-la et refacturez la TVA si necessaire. Un numero corrige par le client est verifie de nouveau automatiquement.';
$_MODULE['<{vatnumber}prestashop>intro_eee81301e59ec7f49d779ad15273ef04'] = 'Les numeros rejetes sont retires automatiquement des adresses des clients (reglage dans l\'onglet Parametres).';
$_MODULE['<{vatnumber}prestashop>intro_39d2c6171b29dfb08bbca6ab2861440d'] = 'Les numeros rejetes restent sur les adresses des clients. Dans l\'onglet Parametres, vous pouvez les faire retirer automatiquement.';
$_MODULE['<{vatnumber}prestashop>vatnumber_fd7933d29ee75710500907bb51616f37'] = 'Numeros rejetes (%d)';
$_MODULE['<{vatnumber}prestashop>vatnumber_c168294e867ffbd1b55009c5166e2abd'] = 'Verifier aussi les numeros de votre propre pays';
$_MODULE['<{vatnumber}prestashop>vatnumber_29ba70bd28bf912c9c5972e421824ed0'] = 'Les clients de votre propre pays paient toujours la TVA, leur numero n\'est donc normalement verifie que sur son format. Activez cette option pour faire confirmer aussi ces numeros par VIES, afin qu\'un numero inexistant ne puisse pas etre enregistre.';
$_MODULE['<{vatnumber}prestashop>vatnumber_516390087ffcfb67655ef69db2decf35'] = 'Utile lorsque les numeros de TVA sont transmis a votre comptabilite ou a un autre systeme qui refuse les numeros inconnus. La tache planifiee verifie de toute facon les numeros nationaux enregistres.';
$_MODULE['<{vatnumber}prestashop>vatnumber_ae99eed504a1c929083b3c2fb2d7efc0'] = 'Retirer les numeros rejetes des adresses';
$_MODULE['<{vatnumber}prestashop>vatnumber_4204f91300a46cc20b1df728455afdfc'] = 'Lorsque VIES rejette un numero de TVA, il est retire des adresses des clients qui le portent, afin qu\'il n\'apparaisse plus sur les factures ni dans votre comptabilite. Chaque suppression est inscrite dans le journal de la boutique.';
$_MODULE['<{vatnumber}prestashop>vatnumber_96c0952eece4b01740f11939a945a403'] = 'S\'applique aux rejets par la tache planifiee et par la verification manuelle ci-dessous. Les commandes deja passees gardent leur adresse telle quelle : une adresse utilisee dans des commandes est remplacee par une copie sans numero, l\'ancienne reste liee a ces commandes.';
$_MODULE['<{vatnumber}prestashop>vatnumber_4d692c4d3c6e343264d479d43baccf93'] = 'Le numero a ete retire de %d adresse(s) client, voir le journal de la boutique.';
$_MODULE['<{vatnumber}prestashop>vatnumber_0aae4064fe2235fc63c5ebe63b2e7f00'] = 'La base de donnees TVA de %s est surchargee en ce moment (trop de demandes simultanees). Attendez une minute et reessayez.';
$_MODULE['<{vatnumber}prestashop>vatnumber_f3325ec82f556a83edbdef1f468169b2'] = 'VIES est surcharge en ce moment (trop de demandes simultanees). Attendez une minute et reessayez.';
$_MODULE['<{vatnumber}prestashop>vatnumber_a33a30a6e18735bbf0d8ca3e84175a9c'] = 'La base de donnees TVA de %s est temporairement indisponible. Reessayez plus tard.';
$_MODULE['<{vatnumber}prestashop>vatnumber_0f15e2242b4fe9c09d22e20f9bafeb03'] = 'Verification en arriere-plan : la base de donnees TVA de %s est surchargee ou indisponible (%s) ; ses numeros seront verifies a la prochaine execution';
$_MODULE['<{vatnumber}prestashop>vatnumber_fc37bc40660182e90ee967e9076ff409'] = 'Verification en arriere-plan : l\'adresse de %s n\'a pas pu etre recherchee : %s';
$_MODULE['<{vatnumber}prestashop>vatnumber_2ecb26789c1650ee22af49c4aa344a5a'] = 'Le retrait du numero de TVA rejete %s des adresses des clients a echoue : %s';
$_MODULE['<{vatnumber}prestashop>vatnumber_5ad2dcf36ac0fd1168003e2cebdc14c7'] = 'Le numero de TVA rejete %s a ete retire de l\'adresse %d.';
$_MODULE['<{vatnumber}prestashop>vatnumber_1f4c4585f2ff3f08c14af9945af8eb2f'] = 'Le numero de TVA rejete %s a ete retire chez le client : l\'adresse %d a ete remplacee par l\'adresse %d sans numero de TVA ; les commandes gardent l\'ancienne adresse.';
